package rules

import (
	"bytes"
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"fmt"

	"gopkg.in/yaml.v3"
)

// Pre-parsed embedded content.
//
// A guard-mode hook is a fresh process per tool call and parses the
// embedded packs every time. yaml.v3's scanner is two thirds of that cost
// (measured: 18 ms for 300 rules against a 15 ms start-up budget), so the
// build ships the same content a second time as already parsed node trees
// in the compact form below, generated by `go generate` (cmd/rulescache)
// into packs/embedded.cache.
//
// The YAML stays the source of truth. The cache records a SHA-256 over the
// exact source bytes it was made from, and LoadEmbedded uses it only when
// that digest matches the embedded YAML and the cache decodes cleanly;
// otherwise it parses the YAML (slower, never different). Decoded trees go
// through the same structural checks and the same compiler as parsed ones.
//
// The cache is embedded in the binary rather than written to a user cache
// directory at run time: that directory is writable by the agent the guard
// is meant to constrain, and a planted "cache" would replace the rules.

const (
	cacheMagic    = "SPRNC1\n"
	cacheFileName = "packs/embedded.cache"
	maxCacheBytes = 64 << 20
	maxCacheStrs  = 1 << 20
	maxCacheFiles = 1024
)

var errCache = errors.New("rules: invalid content cache")

// sourceDigest is the SHA-256 over every content file (sorted by name):
// name, NUL, 8-byte big-endian length, bytes.
func sourceDigest(files map[string][]byte) [sha256.Size]byte {
	h := sha256.New()
	var n [8]byte
	for _, name := range sortedFileNames(files) {
		if fileRole(name) == "" {
			continue
		}
		h.Write([]byte(name))
		h.Write([]byte{0})
		binary.BigEndian.PutUint64(n[:], uint64(len(files[name])))
		h.Write(n[:])
		h.Write(files[name])
	}
	var out [sha256.Size]byte
	h.Sum(out[:0])
	return out
}

// EncodeCache parses rule content (the same file map Load takes) and
// returns its pre-parsed form for packs/embedded.cache. It fails when the
// content does not load: a cache is never made for content that would be
// rejected. The output is deterministic.
func EncodeCache(files map[string][]byte) ([]byte, error) {
	var srcs []sourceFile
	for _, n := range sortedFileNames(files) {
		src, ok, err := parseSource(n, files[n])
		if err != nil {
			return nil, err
		}
		if ok {
			srcs = append(srcs, src)
		}
	}
	if _, err := loadSources(srcs, true); err != nil {
		return nil, err
	}
	enc := cacheEncoder{idx: map[string]uint64{}}
	for _, s := range srcs {
		enc.str(s.name)
		enc.collect(s.root)
	}
	var out bytes.Buffer
	out.WriteString(cacheMagic)
	d := sourceDigest(files)
	out.Write(d[:])
	putUvarint(&out, uint64(len(enc.strs)))
	for _, s := range enc.strs {
		putUvarint(&out, uint64(len(s)))
	}
	for _, s := range enc.strs {
		out.WriteString(s)
	}
	putUvarint(&out, uint64(len(srcs)))
	for _, s := range srcs {
		putUvarint(&out, enc.idx[s.name])
		putUvarint(&out, uint64(s.size))
		putUvarint(&out, uint64(countNodes(s.root)))
		enc.node(&out, s.root)
	}
	return out.Bytes(), nil
}

type cacheEncoder struct {
	strs []string
	idx  map[string]uint64
}

func (e *cacheEncoder) str(s string) uint64 {
	if i, ok := e.idx[s]; ok {
		return i
	}
	i := uint64(len(e.strs))
	e.strs = append(e.strs, s)
	e.idx[s] = i
	return i
}

func (e *cacheEncoder) collect(n *yaml.Node) {
	e.str(n.Tag)
	e.str(n.Value)
	for _, c := range n.Content {
		e.collect(c)
	}
}

func (e *cacheEncoder) node(w *bytes.Buffer, n *yaml.Node) {
	w.WriteByte(byte(n.Kind))
	w.WriteByte(byte(n.Style))
	putUvarint(w, e.idx[n.Tag])
	putUvarint(w, e.idx[n.Value])
	putUvarint(w, uint64(n.Line))
	putUvarint(w, uint64(n.Column))
	putUvarint(w, uint64(len(n.Content)))
	for _, c := range n.Content {
		e.node(w, c)
	}
}

func countNodes(n *yaml.Node) int {
	c := 1
	for _, k := range n.Content {
		c += countNodes(k)
	}
	return c
}

func putUvarint(w *bytes.Buffer, v uint64) {
	var b [binary.MaxVarintLen64]byte
	w.Write(b[:binary.PutUvarint(b[:], v)])
}

// decodeCache returns the parsed files of a cache made from content whose
// sourceDigest is want. Every structural property is validated: the cache
// is embedded and trusted, but a decoder that trusts its input is one bug
// away from a panic in every hook process.
func decodeCache(b []byte, want [sha256.Size]byte) (srcs []sourceFile, err error) {
	defer func() {
		if recover() != nil {
			srcs, err = nil, errCache
		}
	}()
	if len(b) > maxCacheBytes || len(b) < len(cacheMagic)+sha256.Size || string(b[:len(cacheMagic)]) != cacheMagic {
		return nil, errCache
	}
	r := &cacheReader{b: b, off: len(cacheMagic)}
	if !bytes.Equal(r.take(sha256.Size), want[:]) {
		return nil, fmt.Errorf("%w: made from different content (run go generate ./internal/rules)", errCache)
	}
	ns := r.count(maxCacheStrs)
	lens := make([]int, ns)
	total := 0
	for i := range lens {
		lens[i] = r.count(maxCacheBytes)
		total += lens[i]
	}
	if r.err != nil || total > len(b) {
		return nil, errCache
	}
	// One allocation for every string; nodes share substrings of it.
	all := string(r.take(total))
	r.strs = make([]string, ns)
	off := 0
	for i, l := range lens {
		r.strs[i] = all[off : off+l]
		off += l
	}
	nf := r.count(maxCacheFiles)
	for i := 0; i < nf && r.err == nil; i++ {
		name := r.str()
		size := r.count(maxCacheBytes)
		nodes := r.count(maxYAMLNodes)
		if r.err != nil || nodes == 0 {
			return nil, errCache
		}
		r.arena = make([]yaml.Node, nodes)
		r.ptrs = make([]*yaml.Node, nodes-1)
		r.used, r.pused = 0, 0
		root := r.node(0)
		if r.err != nil || r.used != nodes || r.pused != nodes-1 {
			return nil, errCache
		}
		count := 0
		if err := checkNode(root, 0, &count); err != nil {
			return nil, errCache
		}
		if fileRole(name) == "" {
			return nil, errCache
		}
		srcs = append(srcs, sourceFile{name: name, size: size, root: root})
	}
	if r.err != nil || r.off != len(b) {
		return nil, errCache
	}
	return srcs, nil
}

type cacheReader struct {
	b     []byte
	off   int
	err   error
	strs  []string
	arena []yaml.Node
	ptrs  []*yaml.Node
	used  int
	pused int
}

func (r *cacheReader) fail() { r.err = errCache }

func (r *cacheReader) uvarint() uint64 {
	if r.err != nil {
		return 0
	}
	v, n := binary.Uvarint(r.b[r.off:])
	if n <= 0 {
		r.fail()
		return 0
	}
	r.off += n
	return v
}

// count reads a non-negative integer no larger than max.
func (r *cacheReader) count(max int) int {
	v := r.uvarint()
	if v > uint64(max) {
		r.fail()
		return 0
	}
	return int(v)
}

func (r *cacheReader) take(n int) []byte {
	if r.err != nil || n < 0 || n > len(r.b)-r.off {
		r.fail()
		return nil
	}
	out := r.b[r.off : r.off+n]
	r.off += n
	return out
}

func (r *cacheReader) byte1() byte {
	if p := r.take(1); p != nil {
		return p[0]
	}
	return 0
}

func (r *cacheReader) str() string {
	i := r.uvarint()
	if r.err != nil || i >= uint64(len(r.strs)) {
		r.fail()
		return ""
	}
	return r.strs[i]
}

// node decodes one node in pre-order into the arena. The children of a
// node occupy a contiguous run of r.ptrs reserved before they are decoded,
// with capacity capped so an append can never overwrite a neighbour.
func (r *cacheReader) node(depth int) *yaml.Node {
	if r.err != nil || depth > maxYAMLDepth+1 || r.used >= len(r.arena) {
		r.fail()
		return nil
	}
	n := &r.arena[r.used]
	r.used++
	n.Kind = yaml.Kind(r.byte1())
	switch n.Kind {
	case yaml.SequenceNode, yaml.MappingNode, yaml.ScalarNode:
	default:
		// Documents are unwrapped before encoding and aliases are
		// rejected by the parser.
		r.fail()
		return nil
	}
	n.Style = yaml.Style(r.byte1())
	n.Tag = r.str()
	n.Value = r.str()
	n.Line = r.count(1 << 30)
	n.Column = r.count(1 << 30)
	k := r.count(len(r.ptrs) - r.pused)
	if r.err != nil {
		return nil
	}
	if n.Kind == yaml.ScalarNode && k > 0 || n.Kind == yaml.MappingNode && k%2 != 0 {
		r.fail()
		return nil
	}
	if k > 0 {
		kids := r.ptrs[r.pused : r.pused+k : r.pused+k]
		r.pused += k
		for i := range kids {
			kids[i] = r.node(depth + 1)
			if r.err != nil {
				return nil
			}
		}
		n.Content = kids
	}
	return n
}
